SELECT d.d_year, i.i_brand, SUM(inv.inv_quantity_on_hand) AS total_quantity, AVG(i.i_current_price) AS avg_price FROM inventory inv JOIN date_dim d ON inv.inv_date_sk = d.d_date_sk JOIN item i ON inv.inv_item_sk = i.i_item_sk WHERE d.d_year = 1934 AND i.i_brand = 'brandbrand #4                                     ' GROUP BY d.d_year, i.i_brand HAVING SUM(inv.inv_quantity_on_hand) > 676 ORDER BY total_quantity DESC LIMIT 500
